const existing = $('Sheets — Cours existants').all().map(i => i.json.Titre || '').filter(Boolean);
const localItems = ($('Google Search — Besoins locaux').first().json?.items || []).map(i => ({ title: i.title, snippet: i.snippet, url: i.link }));
const intlItems = ($('Google Search — Benchmark international').first().json?.items || []).map(i => ({ title: i.title, snippet: i.snippet, url: i.link }));

return [{ json: { existing_courses: existing, local_search_results: localItems, international_results: intlItems } }];

const response = $input.first().json;
const today = new Date().toISOString().split('T')[0];

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing propositions de cours: ' + e.message);
}

const courses = (parsed.course_proposals || []).map(c => ({
  Date: today,
  Titre: c.title,
  Niveau: c.level,
  Audience: c.target_audience,
  Besoin_Local: c.why_needed_locally,
  Duree: `${c.estimated_duration_hours}h (${c.estimated_modules} modules, ${c.estimated_lessons} leçons)`,
  Score: c.priority_score,
  Status: 'nouveau',
  // Extra data for WF-11
  slug: c.slug_suggested,
  category: c.category,
  objectives: JSON.stringify(c.learning_objectives),
  prerequisites: JSON.stringify(c.prerequisites),
  outline: JSON.stringify(c.outline_preview),
  price_range: c.suggested_price_range,
  monetization: c.monetization_potential
}));

return courses.map(c => ({ json: c }));
